import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBarlow = makeLoadFont('Barlow');

// Load Barlow font at module level
const { fontFamily: barlowFamily } = loadBarlow();

// Inline single Zod schema containing all parameters


export type PokerHUDRecreationProps = Record<string, any>;

// Playing Card Subcomponent
const PlayingCard: React.FC<{
  value: string;
  suit: "♠" | "♥" | "♦" | "♣";
  flipProgress: number; // 0 to 1
}> = ({ value, suit, flipProgress }) => {
  const isRed = suit === "♥" || suit === "♦";
  
  // Custom spring curve mapped to 3D rotation
  const rotateY = interpolate(flipProgress, [0, 1], [180, 0]);
  const translateY = interpolate(flipProgress, [0, 1], [15, 0]);
  const opacity = interpolate(flipProgress, [0, 0.2], [0, 1], { extrapolateRight: "clamp" });

  return (
    <div
      style={{
        width: 100,
        height: 135,
        perspective: 800,
        marginRight: 8,
        position: "relative",
        opacity,
        transform: `translateY(${translateY}px)`,
        transition: "none",
      }}
    >
      <div
        style={{
          width: "100%",
          height: "100%",
          transformStyle: "preserve-3d",
          transform: `rotateY(${rotateY}deg)`,
          position: "relative",
          transition: "none",
        }}
      >
        {/* Card Front */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backfaceVisibility: "hidden",
            backgroundColor: "#ffffff",
            borderRadius: 12,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "space-between",
            border: "2px solid #e2e8f0",
            boxShadow: "0 10px 20px rgba(0,0,0,0.4)",
            padding: "8px 10px",
            boxSizing: "border-box",
            transition: "none",
          }}
        >
          {/* Top Left Mini Value */}
          <div style={{ alignSelf: "flex-start", display: "flex", flexDirection: "column", alignItems: "center", lineHeight: 0.9 }}>
            <span style={{ fontSize: 24, fontWeight: 900, color: isRed ? "#dc2626" : "#0f172a" }}>{value}</span>
            <span style={{ fontSize: 18, color: isRed ? "#dc2626" : "#0f172a" }}>{suit}</span>
          </div>
          
          {/* Main Center Suit */}
          <div style={{ fontSize: 44, color: isRed ? "#dc2626" : "#0f172a", lineHeight: 1, marginTop: -4 }}>
            {suit}
          </div>

          {/* Bottom Right Inverted Mini Value */}
          <div style={{ alignSelf: "flex-end", display: "flex", flexDirection: "column", alignItems: "center", lineHeight: 0.9, transform: "rotate(180deg)" }}>
            <span style={{ fontSize: 24, fontWeight: 900, color: isRed ? "#dc2626" : "#0f172a" }}>{value}</span>
            <span style={{ fontSize: 18, color: isRed ? "#dc2626" : "#0f172a" }}>{suit}</span>
          </div>
        </div>

        {/* Card Back */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backfaceVisibility: "hidden",
            transform: "rotateY(180deg)",
            backgroundColor: "#1e293b",
            borderRadius: 12,
            border: "4px solid #ffffff",
            boxShadow: "0 10px 25px rgba(0,0,0,0.4)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxSizing: "border-box",
            overflow: "hidden",
            transition: "none",
          }}
        >
          {/* Gorgeous geometric vector diamond poker back design */}
          <div
            style={{
              width: "100%",
              height: "100%",
              background: `repeating-linear-gradient(45deg, #991b1b, #991b1b 8px, #7f1d1d 8px, #7f1d1d 16px)`,
              opacity: 0.95,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
            }}
          >
            <div style={{
              width: "75%",
              height: "80%",
              border: "2px solid rgba(255, 255, 255, 0.25)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}>
              <div style={{ width: 16, height: 16, border: "2px solid #fef08a", transform: "rotate(45deg)", background: "transparent" }} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const PokerHUDRecreation: React.FC<PokerHUDRecreationProps> = ({
  backgroundColor = "#0e1a2f",
  transparentBackground = false,
  durationInSeconds = 10,
  players = [
    {
      name: "HELLMUTH",
      chips: "$20.2K",
      action: "CALL $300",
      actionType: "call",
      percentage: "29%",
      profileImage: "https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=250&q=80",
      positionBadge: "SB",
      isActive: true,
      cards: [
        { value: "9", suit: "♠" },
        { value: "8", suit: "♠" }
      ]
    },
    {
      name: "MONEYMAKER",
      chips: "$28.7K",
      action: "CALL $200",
      actionType: "call",
      percentage: "45%",
      profileImage: "https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=250&q=80",
      positionBadge: "BB",
      isActive: false,
      cards: [
        { value: "A", suit: "♣" },
        { value: "J", suit: "♥" }
      ]
    },
    {
      name: "BLEZNICK",
      chips: "$88.2K",
      action: "RAISE TO $2,400",
      actionType: "raise",
      percentage: "25%",
      profileImage: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=250&q=80",
      positionBadge: "BTN",
      isActive: false,
      cards: [
        { value: "K", suit: "♠" },
        { value: "J", suit: "♠" }
      ]
    }
  ]
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background and Layout calculations
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Stagger parameters
  const staggerOffset = 12; // stagger delay between HUD lines

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: barlowFamily,
        color: "#ffffff",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Background Graphic Accents */}
      {!transparentBackground && (
        <AbsoluteFill style={{ transition: "none" }}>
          {/* Spotlight vignette overlay */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              background: "radial-gradient(circle, rgba(14,26,47,0.3) 0%, rgba(5,10,18,0.9) 100%)",
              zIndex: 1,
              transition: "none",
            }}
          />
          {/* Deep felt texture circles */}
          <div
            style={{
              position: "absolute",
              width: "120%",
              height: "120%",
              left: "-10%",
              top: "-10%",
              border: "4px solid rgba(255, 255, 255, 0.03)",
              borderRadius: "50%",
              zIndex: 0,
              pointerEvents: "none",
              transition: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              width: "80%",
              height: "80%",
              left: "10%",
              top: "10%",
              border: "2px solid rgba(255, 255, 255, 0.02)",
              borderRadius: "50%",
              zIndex: 0,
              pointerEvents: "none",
              transition: "none",
            }}
          />
        </AbsoluteFill>
      )}

      {/* Main Players List Container */}
      <div
        style={{
          position: "absolute",
          left: 100,
          top: 200,
          display: "flex",
          flexDirection: "column",
          gap: 75, // Increased vertical spacing for overlapping cards visual room
          zIndex: 5,
          width: 900,
          transition: "none",
        }}
      >
        {players.map((player, index) => {
          // HUD Row Entrance Slide/Fade Spring
          const entranceSpring = spring({
            frame: frame - index * staggerOffset,
            fps,
            config: { damping: 16, mass: 0.9 },
          });

          const rowX = interpolate(entranceSpring, [0, 1], [-300, 0]);
          const rowOpacity = interpolate(entranceSpring, [0, 1], [0, 1]);

          // Cards Reveal Timings (Sequential Staggered Reveals)
          // P1: Card 1 starts at frame 50, Card 2 at frame 68
          // P2: Card 1 starts at frame 86, Card 2 at frame 104
          // P3: Card 1 starts at frame 122, Card 2 at frame 140
          const card1StartFrame = 50 + index * 36;
          const card2StartFrame = 68 + index * 36;

          const card1FlipProgress = spring({
            frame: frame - card1StartFrame,
            fps,
            config: { damping: 12, mass: 0.8 },
          });

          const card2FlipProgress = spring({
            frame: frame - card2StartFrame,
            fps,
            config: { damping: 12, mass: 0.8 },
          });

          // Action bar / percentage box entry timing
          // Fade/scale in as the second card of this player finishes flipping
          const extraRevealFrame = card2StartFrame + 12;
          const extraRevealSpring = spring({
            frame: frame - extraRevealFrame,
            fps,
            config: { damping: 15 },
          });

          const extraOpacity = interpolate(extraRevealSpring, [0, 1], [0, 1]);
          const extraScale = interpolate(extraRevealSpring, [0, 1], [0.85, 1]);

          // Color palette mapping based on ActionType
          let actionGradient = "linear-gradient(90deg, #1e3a8a 0%, #1e40af 100%)"; // default blue
          if (player.actionType === "raise") {
            actionGradient = "linear-gradient(90deg, #991b1b 0%, #b91c1c 100%)"; // aggressive red
          } else if (player.actionType === "check") {
            actionGradient = "linear-gradient(90deg, #065f46 0%, #047857 100%)"; // stable green/teal
          } else if (player.actionType === "fold") {
            actionGradient = "linear-gradient(90deg, #374151 0%, #4b5563 100%)"; // muted gray
          }

          return (
            <div
              key={player.name}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "flex-end",
                transform: `translateX(${rowX}px)`,
                opacity: rowOpacity,
                position: "relative",
                height: 180,
                transition: "none",
              }}
            >
              {/* Profile Box & Chip Stack Badge */}
              <div
                style={{
                  position: "relative",
                  width: 155,
                  height: 155,
                  display: "flex",
                  flexDirection: "column",
                  zIndex: 4,
                  transition: "none",
                }}
              >
                {/* Profile Image with outline crop */}
                <div
                  style={{
                    flex: 1,
                    backgroundColor: "#111827",
                    border: player.isActive ? "4px solid #facc15" : "3px solid #e2e8f0",
                    borderBottom: "none",
                    borderRadius: "16px 16px 0 0",
                    overflow: "hidden",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    boxShadow: "0 10px 20px rgba(0,0,0,0.3)",
                    transition: "none",
                  }}
                >
                  <Img
                    src={player.profileImage}
                    style={{
                      width: "100%",
                      height: "100%",
                      objectFit: "cover",
                      transition: "none",
                    }}
                  />
                </div>
                {/* Chip Value/Stack Banner */}
                <div
                  style={{
                    height: 44,
                    backgroundColor: "#000000",
                    borderRadius: "0 0 16px 16px",
                    border: player.isActive ? "4px solid #facc15" : "3px solid #e2e8f0",
                    borderTop: "none",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 22,
                    fontWeight: 900,
                    color: player.isActive ? "#facc15" : "#ffffff",
                    boxShadow: "0 10px 20px rgba(0,0,0,0.3)",
                    transition: "none",
                  }}
                >
                  {player.chips}
                </div>
              </div>

              {/* Middle Section: Cards & HUD Labels */}
              <div
                style={{
                  position: "relative",
                  height: 215, // Expanded height to container overlapping cards + name + action
                  width: 530,
                  marginLeft: 15,
                  zIndex: 3,
                  transition: "none",
                }}
              >
                {/* Absolute Playing Cards Layer - Pop up from behind name bar */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 20,
                    display: "flex",
                    flexDirection: "row",
                    zIndex: 1,
                    transition: "none",
                  }}
                >
                  {player.cards[0] && (
                    <PlayingCard
                      value={player.cards[0].value}
                      suit={player.cards[0].suit}
                      flipProgress={card1FlipProgress}
                    />
                  )}
                  {player.cards[1] && (
                    <PlayingCard
                      value={player.cards[1].value}
                      suit={player.cards[1].suit}
                      flipProgress={card2FlipProgress}
                    />
                  )}
                </div>

                {/* Name Banner & Position Badge */}
                <div
                  style={{
                    position: "absolute",
                    bottom: 50,
                    left: 0,
                    width: "100%",
                    height: 58,
                    background: player.isActive 
                      ? "linear-gradient(90deg, #b91c1c 0%, #dc2626 100%)" 
                      : "linear-gradient(90deg, #1e293b 0%, #334155 100%)",
                    border: player.isActive ? "3px solid #ffd700" : "2px solid rgba(255,255,255,0.1)",
                    borderRadius: 8,
                    display: "flex",
                    alignItems: "center",
                    paddingLeft: 20,
                    boxSizing: "border-box",
                    boxShadow: "0 8px 20px rgba(0,0,0,0.4)",
                    zIndex: 2,
                    transition: "none",
                  }}
                >
                  <span
                    style={{
                      fontSize: 28,
                      fontWeight: 900,
                      letterSpacing: "1.5px",
                      color: "#ffffff",
                    }}
                  >
                    {player.name}
                  </span>

                  {/* Position Badge overlay */}
                  {player.positionBadge && (
                    <div
                      style={{
                        position: "absolute",
                        right: 15,
                        top: -15,
                        backgroundColor: "#ffffff",
                        color: "#0f172a",
                        padding: "4px 10px",
                        borderRadius: 6,
                        fontWeight: 900,
                        fontSize: 16,
                        boxShadow: "0 5px 15px rgba(0,0,0,0.3)",
                        border: "1px solid rgba(0,0,0,0.1)",
                        zIndex: 5,
                        transition: "none",
                      }}
                    >
                      {player.positionBadge}
                    </div>
                  )}
                </div>

                {/* Dynamic Action Overlay bar */}
                <div
                  style={{
                    position: "absolute",
                    bottom: 0,
                    left: 0,
                    width: "100%",
                    height: 50,
                    background: actionGradient,
                    borderRadius: "0 0 10px 10px",
                    display: "flex",
                    alignItems: "center",
                    paddingLeft: 20,
                    boxSizing: "border-box",
                    boxShadow: "0 10px 25px rgba(0,0,0,0.4)",
                    zIndex: 2,
                    opacity: extraOpacity,
                    transform: `scale(${extraScale})`,
                    transformOrigin: "bottom left",
                    transition: "none",
                  }}
                >
                  <span
                    style={{
                      fontSize: 22,
                      fontWeight: 800,
                      letterSpacing: "1px",
                      color: "#ffffff",
                    }}
                  >
                    {player.action}
                  </span>
                </div>
              </div>

              {/* Far Right: Equity / Win Percentage Box */}
              <div
                style={{
                  width: 110,
                  height: 70,
                  backgroundColor: "rgba(15, 23, 42, 0.95)",
                  border: "2px solid rgba(255, 255, 255, 0.15)",
                  borderRadius: 12,
                  marginLeft: 15,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  boxShadow: "0 10px 25px rgba(0,0,0,0.5)",
                  zIndex: 2,
                  opacity: extraOpacity,
                  transform: `scale(${extraScale})`,
                  transformOrigin: "bottom center",
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontSize: 32,
                    fontWeight: 900,
                    color: "#34d399", // dynamic professional look green equity indicator
                    letterSpacing: "0.5px",
                  }}
                >
                  {player.percentage}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default PokerHUDRecreation;